)

func ids(rows []store.Record) []string {
 out := make([]string, len(rows))
 for i, row := range rows { out[i] = row.ID }
 return out
}

func TestMalformedRecordsNeverReturnPartialSuccess(t *testing.T) {
 c := writeCatalog(t, "{\"id\":\"first\"}\nnot-json\n")
 if rows, err := store.Load(c.Path); err == nil || len(rows) != 0 { t.Fatalf("load=%v err=%v", rows, err) }
 if rows, err := c.Find("book"); err == nil || len(rows) != 0 { t.Fatalf("find=%v err=%v", rows, err) }
 if rows, err := c.Paginate("", 0, 2); err == nil || len(rows) != 0 { t.Fatalf("page=%v err=%v", rows, err) }
 missing := catalog.Catalog{Path: filepath.Join(t.TempDir(), "missing")}
 if _, err := missing.Paginate("", 0, 1); !errors.Is(err, os.ErrNotExist) { t.Fatalf("missing error=%v", err) }
}

func TestFilteringPreservesExactCategoriesAndFileOrder(t *testing.T) {
 c := writeCatalog(t, "{\"id\":\"c\",\"category\":\"book\"}\n{\"id\":\"aa\",\"category\":\"tool\"}\n{\"id\":\"a\",\"category\":\"book\"}\n{\"id\":\"b\",\"category\":\"book\"}\n")
 for _, tc := range []struct { category string; want []string }{
  {"book", []string{"c","a","b"}}, {"", []string{"c","aa","a","b"}}, {"Book", []string{}}, {"missing", []string{}},
 } {
  rows, err := c.Find(tc.category)
  if err != nil || !reflect.DeepEqual(ids(rows), tc.want) { t.Fatalf("find(%q)=%v err=%v", tc.category, ids(rows), err) }
 }
 if rows, err := c.Paginate("book", 1, 1); err != nil || !reflect.DeepEqual(ids(rows), []string{"b"}) { t.Fatalf("middle page=%v err=%v", rows, err) }
 if rows, err := c.Paginate("book", 0, 99); err != nil || !reflect.DeepEqual(ids(rows), []string{"a","b","c"}) { t.Fatalf("full page=%v err=%v", rows, err) }
 if rows, err := c.Paginate("", 0, 2); err != nil || !reflect.DeepEqual(ids(rows), []string{"a","aa"}) { t.Fatalf("unfiltered page=%v err=%v", rows, err) }
 if rows, err := c.Paginate("book", 3, 1); err != nil || len(rows) != 0 { t.Fatalf("past end=%v err=%v", rows, err) }
 if rows, err := c.List(); err != nil || !reflect.DeepEqual(ids(rows), []string{"c","aa","a","b"}) { t.Fatalf("list after paging=%v err=%v", rows, err) }
 for _, bounds := range [][2]int{{-1,1},{0,0},{0,-1}} {
  if _, err := c.Paginate("book", bounds[0], bounds[1]); err == nil { t.Fatalf("accepted invalid bounds %v", bounds) }
 }
}

