		port, err := strconv.Atoi(raw)
		if err != nil {
			return Config{}, err
		}
		c.Port = port
	}
	if raw, ok := values["retries"]; ok {
		retries, err := strconv.Atoi(raw)
		if err != nil {
			return Config{}, err
		}
		c.Retries = retries
	}
	return c, nil
}

