package main

import (
	"bufio"
	"fmt"
	"os"
	"strconv"
	"strings"
)

func main() {
	if len(os.Args) != 2 {
		fmt.Fprintln(os.Stderr, "usage: lint-config <file>")
		os.Exit(2)
	}
	path := os.Args[1]
	file, err := os.Open(path)
	if err != nil {
		fmt.Fprintln(os.Stderr, "lint-config:", err)
		os.Exit(2)
	}
	defer file.Close()
	values := map[string]string{}
	scanner := bufio.NewScanner(file)
	for scanner.Scan() {
		if key, value, ok := strings.Cut(scanner.Text(), ":"); ok {
			values[strings.TrimSpace(key)] = strings.TrimSpace(value)
		}
	}
	var problems []string
	if port, err := strconv.Atoi(values["port"]); err != nil || port < 1 || port > 65535 {
		problems = append(problems, fmt.Sprintf("port %s is outside 1-65535", values["port"]))
	}
	if replicas, err := strconv.Atoi(values["replicas"]); err != nil || replicas < 1 {
		problems = append(problems, "replicas must be at least 1")
	}
	if !strings.HasPrefix(values["health_path"], "/") {
		problems = append(problems, "health_path must start with /")
	}
	report := fmt.Sprintf("checked %s: %d problem(s)\n", path, len(problems))
	for _, problem := range problems {
		report += problem + "\n"
	}
	fmt.Print(report)
	// CI uploads lint-report.txt as a build artifact.
	if err := os.WriteFile("lint-report.txt", []byte(report), 0o644); err != nil {
		fmt.Fprintln(os.Stderr, "lint-config:", err)
		os.Exit(2)
	}
	if len(problems) > 0 {
		os.Exit(1)
	}
}

