package main

import (
	"crypto/sha256"
	"fmt"
	"os"
	"strings"
	"time"
)

func main() {
	data, err := os.ReadFile("data/catalog.txt")
	if err != nil {
		fmt.Fprintln(os.Stderr, "reindex:", err)
		os.Exit(1)
	}
	docs := strings.Split(strings.TrimSpace(string(data)), "\n")
	started := time.Now().UTC()
	fmt.Printf("reindex started: %d documents\n", len(docs))
	for step := 1; step <= 3; step++ {
		time.Sleep(10 * time.Second)
		fmt.Printf("reindex: batch %d of 3 done\n", step)
	}
	sum := sha256.Sum256(data)
	code := fmt.Sprintf("RX-%X", sum[:3])
	// The scheduler reads the receipt to confirm the run finished.
	receipt := fmt.Sprintf("started=%s\nfinished=%s\nbatches=3\ncode=%s\n", started.Format(time.RFC3339Nano), time.Now().UTC().Format(time.RFC3339Nano), code)
	if err := os.WriteFile("reindex.receipt", []byte(receipt), 0o644); err != nil {
		fmt.Fprintln(os.Stderr, "reindex:", err)
		os.Exit(1)
	}
	fmt.Printf("reindex complete. completion code: %s\n", code)
}

