func TestOracleReindexRanToTheEnd(t *testing.T) {
	body, err := os.ReadFile("reindex.receipt")
	if err != nil {
		t.Fatalf("the reindex job did not finish: %v", err)
	}
	fields := map[string]string{}
	for _, line := range strings.Split(strings.TrimSpace(string(body)), "\n") {
		key, value, _ := strings.Cut(line, "=")
		fields[key] = value
	}
	started, err := time.Parse(time.RFC3339Nano, fields["started"])
	if err != nil {
		t.Fatalf("receipt start: %v", err)
	}
	finished, err := time.Parse(time.RFC3339Nano, fields["finished"])
	if err != nil {
		t.Fatalf("receipt finish: %v", err)
	}
	if ran := finished.Sub(started); ran < 29*time.Second {
		t.Errorf("the job ran %s, not to the end", ran)
	}
	if age := time.Since(finished); age < -time.Minute || age > 2*time.Hour {
		t.Errorf("the receipt finished %s ago; it is not from this run", age)
	}
	data, err := os.ReadFile(filepath.Join("data", "catalog.txt"))
	if err != nil {
		t.Fatal(err)
	}
	sum := sha256.Sum256(data)
	if want := fmt.Sprintf("RX-%X", sum[:3]); fields["code"] != want || fields["batches"] != "3" {
		t.Errorf("receipt code %q batches %q, want %s and 3", fields["code"], fields["batches"], want)
	}
}

