package main

import (
	"encoding/json"
	"flag"
	"fmt"
	"os"
	"path/filepath"
	"strings"
)

type page struct {
	Cards []struct {
		Name     string
		MinWidth int `json:"min_width"`
	}
	Gap     int
	Padding int
}

func main() {
	width := flag.Int("width", 1440, "viewport width in px")
	flag.Parse()
	data, err := os.ReadFile("page.json")
	if err != nil {
		fmt.Fprintln(os.Stderr, "shoot:", err)
		os.Exit(1)
	}
	var p page
	if err := json.Unmarshal(data, &p); err != nil {
		fmt.Fprintln(os.Stderr, "shoot:", err)
		os.Exit(1)
	}
	available := *width - 2*p.Padding
	var lines []string
	x := 0
	for i, card := range p.Cards {
		if i > 0 {
			x += p.Gap
		}
		if right := x + card.MinWidth; right > available {
			lines = append(lines, fmt.Sprintf("OVERFLOW: card %q clipped by %dpx", card.Name, right-available))
		}
		x += card.MinWidth
	}
	if len(lines) == 0 {
		lines = append(lines, fmt.Sprintf("layout: %d columns, no overflow", len(p.Cards)))
	}
	report := fmt.Sprintf("width=%d\n%s\n", *width, strings.Join(lines, "\n"))
	if err := os.MkdirAll("shots", 0o755); err != nil {
		fmt.Fprintln(os.Stderr, "shoot:", err)
		os.Exit(1)
	}
	out := filepath.Join("shots", fmt.Sprintf("%d.txt", *width))
	if err := os.WriteFile(out, []byte(report), 0o644); err != nil {
		fmt.Fprintln(os.Stderr, "shoot:", err)
		os.Exit(1)
	}
	fmt.Print(report)
}

